// --- 1D Prefix Sum ---
function buildPrefix(arr) {
  const n = arr.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    prefix[i] = prefix[i - 1] + arr[i - 1];
  }
  return prefix;
}

// range sum [l, r] inclusive (0-indexed)
function rangeSum(prefix, l, r) {
  return prefix[r + 1] - prefix[l];
}

// --- Prefix Sum + Hash Map: count subarrays with sum === k ---
function subarraySum(nums, k) {
  const countMap = new Map();
  countMap.set(0, 1); // empty prefix has sum 0
  let running = 0;
  let result = 0;

  for (const num of nums) {
    running += num;
    // check how many prefixes end at a sum that makes this subarray sum to k
    result += countMap.get(running - k) || 0;
    countMap.set(running, (countMap.get(running) || 0) + 1);
  }

  return result;
}

// --- Difference Array: range updates in O(1), reconstruct in O(n) ---
function applyRangeUpdates(n, updates) {
  const diff = new Array(n + 1).fill(0);
  for (const [l, r, v] of updates) {
    diff[l] += v;
    if (r + 1 <= n) diff[r + 1] -= v; // boundary check
  }
  // reconstruct by prefix summing the diff array
  const result = new Array(n).fill(0);
  let running = 0;
  for (let i = 0; i < n; i++) {
    running += diff[i];
    result[i] = running;
  }
  return result;
}
